/**
 * Where the web gateway reaches the Orion NestJS API.
 *
 * On Vercel (services mode) the API is an internal service. The root vercel.json declares a binding on the `ownus` service that makes Vercel
 * inject the API's internal URL into ORION_API_URL (a URL base: the value is generated by Vercel, never set by hand). The API keeps its
 * own `/api/v1` global prefix, so this module appends it. Bindings resolve at runtime inside functions only (not in builds or middleware).
 *
 * Everywhere else (local development, Docker, a separately hosted API) BACKEND_API_URL, or the older NEST_API_URL, is the full API URL
 * including `/api/v1`, exactly as before.
 */

export const API_PREFIX = '/api/v1';
export const DEFAULT_LOCAL_BACKEND = `http://127.0.0.1:4000${API_PREFIX}`;

type Env = Record<string, string | undefined>;

const clean = (v: string | undefined): string => (v ?? '').trim().replace(/\/+$/, '');

/** The API base URL with `/api/v1`, without a trailing slash. */
export function backendBaseUrl(env: Env = process.env): string {
  const bound = clean(env.ORION_API_URL);
  if (bound) return `${bound}${API_PREFIX}`;
  return clean(env.BACKEND_API_URL) || clean(env.NEST_API_URL) || DEFAULT_LOCAL_BACKEND;
}

/**
 * Where the API address came from and whether it can possibly work, for log lines only (never the full URL, which may carry a path).
 * `default-local` on a hosted deployment (Vercel sets `VERCEL`) means nothing was configured: 127.0.0.1 inside a serverless function is
 * never the API, so every request to it fails with "fetch failed".
 */
export function describeBackendTarget(env: Env = process.env): { source: 'service-binding' | 'BACKEND_API_URL' | 'NEST_API_URL' | 'default-local'; host: string; misconfigured: boolean } {
  const source = clean(env.ORION_API_URL) ? 'service-binding' : clean(env.BACKEND_API_URL) ? 'BACKEND_API_URL' : clean(env.NEST_API_URL) ? 'NEST_API_URL' : 'default-local';
  let host = 'unknown';
  try {
    host = new URL(backendBaseUrl(env)).host;
  } catch {
    // keep "unknown"
  }
  const local = /^(127\.0\.0\.1|localhost|\[::1\])(:|$)/.test(host);
  const hosted = !!env.VERCEL || env.NODE_ENV === 'production';
  return { source, host, misconfigured: hosted && local };
}

/**
 * True when the API is a real remote service (a Vercel service binding, or an explicitly configured non-local URL). The gateway proxies
 * the credential routes to it first and falls back to its own handlers only when it is unreachable; against a local API it uses its own.
 */
export function hasRemoteBackend(env: Env = process.env): boolean {
  if (clean(env.ORION_API_URL)) return true;
  const url = clean(env.BACKEND_API_URL);
  return !!url && !url.includes('127.0.0.1') && !url.includes('localhost');
}
